/** How many minutes of the stretch `from` to `to` fall inside the windows. The windows are not changed. */
export function openMinutes(windows: LockWindow[], from: number, to: number): number {
    if (to <= from) return 0;
    let total = 0;
    for (const w of windows) {
        const start = Math.max(from, w.opens);
        const end = Math.min(to, w.closes);
        if (end > start) total += end - start;
    }
    return total;
}

